<?php
declare(strict_types=1); require_once __DIR__.'/../src/auth.php'; require_login(); $u=current_user(); if(!$u){http_response_code(400);exit('Indisponível para login legado.');}$error=null;$success=null;
if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $cur=$_POST['current_password']??'';$new=$_POST['new_password']??'';$conf=$_POST['new_password_confirmation']??''; $s=db()->prepare("SELECT password_hash FROM app_users WHERE id=:i");$s->execute(['i'=>$u['id']]);$hash=$s->fetchColumn(); if(!password_verify($cur,(string)$hash))$error='Senha atual incorreta.'; elseif($new!==$conf)$error='As novas senhas não são iguais.'; elseif(!password_is_strong($new))$error='Use 8 caracteres com maiúscula, minúscula e número.'; else{ db()->prepare("UPDATE app_users SET password_hash=:h,password_changed_at=NOW(),must_change_password=false,failed_login_count=0,locked_until=NULL,updated_at=NOW() WHERE id=:i")->execute(['h'=>password_hash($new,PASSWORD_DEFAULT),'i'=>$u['id']]);audit_log('password_changed','app_user',$u['id']);$success='Senha alterada.'; } }
$pageTitle='Alterar senha';require __DIR__.'/../templates/header.php';?><?php if($error):?><div class="error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($success):?><div class="list-card"><strong><?=htmlspecialchars($success)?></strong></div><?php endif;?><section class="panel"><form method="post" style="max-width:620px"><?=csrf_field()?><div class="form-row"><label>Senha atual</label><input type="password" name="current_password" required></div><div class="form-row"><label>Nova senha</label><input type="password" name="new_password" required></div><div class="form-row"><label>Confirmar nova senha</label><input type="password" name="new_password_confirmation" required></div><button class="btn btn-primary">Alterar senha</button></form></section><?php require __DIR__.'/../templates/footer.php';?>
